*/
:root{--red:$accent;--ink:$textcolor;--soft:#f6f6f6;--line:#e7e7e7;--muted:#81848b;--width:1080px;--header:102px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff;color:var(--ink);font:14px/1.6 Poppins,Arial,sans-serif}a{color:inherit;text-decoration:none}button,input{font:inherit}button{cursor:pointer}button,a,input{touch-action:manipulation}button{color:inherit}img{max-width:100%;height:auto}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #157dc5;outline-offset:4px}[hidden]{display:none!important}.container{width:calc(100% - 40px);max-width:var(--width);margin-inline:auto}.widget{margin:0}.widget-content{overflow-wrap:anywhere}.section{min-width:0;margin:0;padding:0}.mdi-icon{width:24px;height:24px;display:inline-block;vertical-align:middle;fill:currentColor;flex-shrink:0}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.skip-link{position:fixed;left:12px;top:-60px;z-index:200;background:#fff;padding:12px;border:2px solid var(--red)}.skip-link:focus{top:8px}.icon-btn{display:grid;place-items:center;width:40px;height:40px;border:0;background:transparent;border-radius:50%}.icon-btn:hover{background:#00000008}
.site-header{position:sticky;top:0;background:#fff;z-index:100;border-bottom:1px solid var(--line)}.header-inner{display:grid;grid-template-columns:1fr auto;align-items:center;position:relative}.ly-header{padding:19px 0 9px}.brand,.footer-logo{display:inline-flex;align-items:center;gap:5px;font-size:29px;letter-spacing:-1.4px;font-weight:600;line-height:1.1;position:relative}.brand>span,.footer-logo>span{font-weight:800;color:var(--red)}.brand img{display:block;object-fit:contain;width:auto;height:36px;max-width:240px}.brand small{display:none}.header-actions{display:flex;align-items:center;gap:8px}.ly-navigation{grid-column:1/-1;min-width:0}.channel-nav{overflow:auto;scrollbar-width:none}.channel-nav::-webkit-scrollbar{display:none}.nav-list{display:flex;align-items:center;gap:22px;list-style:none;margin:0;padding:0;white-space:nowrap;min-height:43px}.nav-list a{display:block;font-size:14px;font-weight:700;line-height:1.4;padding:9px 0 11px;border-bottom:3px solid transparent}.nav-list a:hover,.nav-list a.is-active{color:var(--red);border-bottom-color:var(--red)}.for-you-bar{background:var(--red);color:#fff}.for-you-inner{display:flex;gap:18px;align-items:center;min-height:48px}.for-you-inner>strong{line-height:1.03;font-size:12px;font-weight:800;flex-shrink:0}.topic-links{display:flex;gap:10px;overflow:auto;scrollbar-width:none;align-items:center;padding:8px 0;white-space:nowrap}.topic-links a{display:inline-flex;padding:4px 14px;border-radius:30px;background:#fff;color:var(--red);font-size:11px;font-weight:500}.topic-links a:hover{background:#ffe6e6}.menu-panel{position:fixed;top:0;right:0;width:min(430px,100%);height:100dvh;overflow:auto;z-index:130;background:#fff;padding:25px;box-shadow:-12px 0 50px #0002}.menu-panel-head{display:flex;align-items:center;justify-content:space-between;padding-bottom:18px;border-bottom:1px solid var(--line);font-size:18px}.drawer-links{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:22px 0}.drawer-links a{padding:10px;border-bottom:1px solid var(--line);font-weight:600}.drawer-links a:hover{color:var(--red)}.drawer-index{display:flex;justify-content:space-between;align-items:center;padding:16px;background:var(--red);color:#fff;border-radius:5px;font-weight:600}.menu-shade{position:fixed;inset:0;z-index:120;background:#0007}
.search-panel{position:absolute;right:max(20px,calc((100vw - var(--width))/2));top:59px;width:min(640px,calc(100vw - 32px));max-height:calc(100dvh - 80px);overflow:auto;padding:12px;background:#171717;color:#fff;box-shadow:0 20px 50px #0004;border-radius:12px;z-index:115}.search-panel-head{display:flex;justify-content:space-between;align-items:center;font-weight:600;font-size:13px}.search-panel-head .icon-btn{width:30px;height:30px}.search-form{display:flex;height:44px;border:1px solid #777;border-radius:9px;background:#404040;overflow:hidden;margin-top:6px}.search-form input{min-width:0;flex:1;padding:0 13px;color:#fff;background:transparent;border:0;font-size:16px;outline-offset:-3px}.search-form input::placeholder{color:#ddd}.search-form button{display:grid;place-items:center;width:48px;border:0;background:transparent;color:#fff}.search-suggestions{display:grid;grid-template-columns:.85fr 1.15fr;gap:18px;margin-top:10px;padding:16px;background:#f9f9f9;color:var(--ink);border:1px solid #ddd;border-radius:12px}.search-suggestions section{min-width:0}.search-suggestions h2{display:flex;align-items:center;gap:7px;font-size:13px;margin:0 0 12px}.search-suggestions h2 .mdi-icon{width:25px;height:25px;padding:4px;color:var(--red);background:#ed1c2415;border-radius:50%}.search-tags{display:flex;flex-wrap:wrap;gap:7px}.search-tags a{padding:5px 10px;border:1px solid #ddd;border-radius:30px;font-size:11px;background:#fff}.search-tags a:hover{color:var(--red);border-color:var(--red)}.search-popular{display:grid;gap:9px}.search-popular p{margin:0;font-size:12px;color:#777}.search-quick-post{display:grid;grid-template-columns:58px 1fr;gap:9px;align-items:center}.search-quick-post .thumb{width:58px;height:44px;border-radius:7px}.search-quick-post strong{font-size:11px;line-height:1.4;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}.search-quick-post small{font-size:9px;color:#888}
