nt-weight:700;letter-spacing:-.3px}.news-row .thumb{width:100%;aspect-ratio:16/10}.row-meta{display:flex;flex-wrap:wrap;gap:8px;font-size:10px;color:#999}.category{color:var(--red);font-size:11px;font-weight:600}.pager{display:flex;justify-content:center;gap:15px;flex-wrap:wrap;margin:28px 0}.pager a,.red-button,.index-link,.comments-link{display:inline-flex;justify-content:center;border:1px solid var(--red);padding:10px 20px;color:var(--red);border-radius:5px;font-size:12px;font-weight:600}.pager a:hover,.red-button:hover,.comments-link:hover{background:var(--red);color:#fff}.page-heading{font-size:32px;line-height:1.4;margin:20px 0 10px}.archive-intro{color:#777}.native-heading{border-bottom:1px solid var(--line);padding-bottom:15px;margin-bottom:25px}.sidebar-column .section-title{font-size:21px}.popular-list{list-style:none;counter-reset:popular;padding:0;margin:0 0 20px}.popular-list li{counter-increment:popular;position:relative;padding:14px 0 14px 29px;border-bottom:1px solid var(--line)}.popular-list li:before{content:counter(popular);position:absolute;top:14px;left:0;font-size:21px;line-height:1.4;font-weight:700;color:var(--red)}.popular-list li a{display:flex;gap:10px;align-items:flex-start}.popular-list img{width:72px;height:56px;object-fit:cover;border-radius:5px}.popular-list h3{font-size:12px;line-height:1.6;margin:0}.sidebar-labels{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:25px}.sidebar-labels a{border:1px solid #ddd;border-radius:30px;padding:6px 12px;font-size:11px}.sidebar-labels a:hover{border-color:var(--red);color:var(--red)}.sidebar-topics ol{padding-left:22px}.sidebar-topics li{padding:8px 0;font-size:13px;font-weight:600}.sidebar-topics li::marker{color:var(--red)}.side-card{display:grid;grid-template-columns:90px 1fr;gap:12px;margin-bottom:18px}.side-card .thumb{width:90px;aspect-ratio:4/3}.side-card h3{font-size:12px;line-height:1.5;margin:0}.sidebar-sticky{position:sticky;top:calc(var(--header) + 12px)}.empty-state{background:var(