.breadcrumbs{display:flex;gap:8px;flex-wrap:wrap;color:#888;font-size:12px;margin:22px 0}.article-head h1{font-size:32px;line-height:1.45;font-weight:700;letter-spacing:-.6px;margin:0 0 18px}.article-byline,.article-date{font-size:11px;color:#888;margin-bottom:6px}.article-byline [itemprop=name]{color:var(--red);font-weight:600}.share-row{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin:18px 0 25px;font-size:11px}.share-row>a,.share-row>button{display:grid;place-items:center;width:31px;height:31px;border-radius:50%;border:0;background:#f2f2f2;color:#555}.share-row .mdi-icon{width:17px;height:17px}.share-row .share-wa{background:#e6f7ee;color:#139653}.share-row .share-fb{background:#eaf0fb;color:#1877f2}.share-row>a:hover,.share-row>button:hover{background:var(--red);color:#fff}.share-status{color:var(--red);width:100%}.post-body{font:16px/1.85 Poppins,Arial,sans-serif;overflow-wrap:anywhere}.post-body img{max-width:100%;height:auto;border-radius:5px}.post-body iframe,.post-body video{max-width:100%}.post-body table{max-width:100%;width:auto}.post-body pre{white-space:pre-wrap;overflow-wrap:anywhere}.post-body h2{font-size:23px;line-height:1.5;margin:30px 0 15px}.post-body h3{font-size:20px}.post-body p{margin:0 0 22px}.post-body a{color:var(--red)}.post-body figure{margin:0 0 23px}.post-body figcaption,.post-body .tr-caption{font-size:11px;color:#888;line-height:1.6}.post-body blockquote{margin:25px 0;padding:15px 20px;border-left:4px solid var(--red);background:#faf5f5}.post-body .tr-caption-container{max-width:100%;margin-left:auto;margin-right:auto}.article-labels{display:flex;gap:8px;flex-wrap:wrap;margin:30px 0}.article-labels a{padding:5px 12px;border-radius:30px;border:1px solid var(--line);font-size:12px;color:var(--red)}.related-target{margin:36px 0}.related-target .news-grid{gap:18px}.related-target h3{font-size:13px}.comments{margin:30px 0}.comment{padding:15px;border-top:1px solid var(--line)}.error-page{text-align:center;padding:60px 15px}.error-page h1{font-size:90px;line-height:1;color:var(--red);margin:0}.footer{background:#2c2e31;color:#fff;margin-top:60px;padding:42px 0 0}.footer-top{display:grid;grid-template-columns:1fr 1fr 1fr;gap:25px}.footer-logo{font-size:32px;grid-column:1/-1;margin-bottom:2px}.footer h2{font-size:14px;margin:0 0 12px}.footer p{font-size:12px;color:#c5c5c7;margin:0;line-height:1.9;max-width:360px}.footer-pages{display:flex;gap:10px 20px;flex-wrap:wrap;font-size:12px}.footer-pages a:hover{color:#ffb3b3}.social-links{display:flex;gap:8px;flex-wrap:wrap}.social-links a{display:grid;place-items:center;width:31px;height:31px;border:1px solid #ffffff42;border-radius:50%}.social-links .mdi-icon{width:17px;height:17px}.social-links a:hover{background:var(--red);border-color:var(--red)}.footer-bottom{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #ffffff20;margin-top:32px;padding-top:17px;padding-bottom:20px;font-size:10px;color:#bbb}.back-top{display:grid;place-items:center;width:32px;height:32px;background:transparent;color:#fff;border:1px solid #ffffff42;border-radius:50%}
.ad-placeholder{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;background:#efefef;color:#9a9a9a;text-align:center;font:11px/1.5 Arial,sans-serif;max-width:100%}.ad-placeholder>span{font-size:9px;letter-spacing:1px;background:#d7d7d7;padding:2px 7px;border-radius:3px;color:#777}.ad-placeholder>small{font-size:10px}.ad-slot{line-height:normal;text-align:center}.ad-slot .widget-content{line-height:normal}.ad-slot img,.ad-slot iframe,.ad-slot ins{max-width:100%}.ad-banner{max-width:728px;margin:25px auto}.ad-banner .ad-placeholder{height:90px}.top-billboard{position:relative;height:250px;clip-path:inset(0);overflow:hidden;background:#f5f5f5}.top-ad-inner{position:fixed;top:0;left:50%;transform:translateX(-50%);width:970px;max-width:100vw}.top-billboard .ad-placeholder{width:970px;height:250px;background:#ededed}.top-ad-caption{display:none}.ad-rail{display:none;position:fixed;top:110px;width:160px;height:600px;max-height:calc(100dvh - 120px);overflow:hidden;z-index:70}.rail-left{right:calc(50% + 560px)}.rail-right{left:calc(50% + 560px)}.ad-rail .ad-placeholder{width:160px;height:600px}.ad-close{position:absolute;top:0;right:0;width:25px;height:25px;border:0;background:#333;color:#fff;font:20px/25px Arial,sans-serif;padding:0;z-index:3}.ad-side{width:300px;max-width:100%;margin:0 auto 30px}.ad-side .ad-placeholder{height:300px}#ttAdSideEnd .ad-placeholder{height:600px}.article-parallax{margin:28px 0;width:100%;clear:both;background:transparent}.ad-window{position:relative;clip-path:inset(0);overflow:hidden;height:300px;background:#f2f2f2}.parallax-inner{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);width:300px;max-width:calc(100vw - 32px);line-height:normal}.parallax-inner .ad-placeholder{width:300px;height:600px}.parallax-inner .article-parallax-slot{margin:0;width:300px;max-width:100%}.parallax-caption{font:9px/15px Arial,sans-serif;height:15px;text-align:center;color:#aaa;background:#f5f5f5}.ad-bottom{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:728px;max-width:100%;z-index:90;background:#fff}.ad-bottom .ad-placeholder{height:90px}.ad-bottom .ad-close{top:-24px;left:50%;right:auto;transform:translateX(-50%);border-radius:12px 12px 0 0;width:76px;height:24px;font:bold 10px/24px Arial,sans-serif;background:var(--red)}.has-bottom-ad{padding-bottom:100px}
