@media(max-width:1000px){.nav-list{gap:19px}.content-columns{grid-template-columns:minmax(0,1fr) 280px;gap:24px}.ad-side{width:280px}.news-row{grid-template-columns:160px 1fr;gap:16px}.news-row h2{font-size:16px}.news-rail .news-card{flex-basis:calc((100% - 40px)/3)}#ttTrending .news-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.hero-copy h1{font-size:24px}.sidebar-sticky{top:calc(var(--header) + 12px)}}
