lex-shrink:0}.footer-top{grid-template-columns:1fr 1fr;gap:24px}.footer-top>#ttAbout{grid-column:1/-1}.footer-information{min-width:0}.footer-pages{gap:8px;font-size:11px;flex-direction:column}.footer-logo{font-size:30px}.footer p{font-size:11px}.ad-banner{margin:24px auto}.related-target .news-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.related-target .news-card:last-child{display:none}}
