/* TBTimes v1.0.1: stable header buttons and edge carousel controls. */
.site-header .icon-btn,.menu-panel .icon-btn{border-radius:4px;background:transparent;box-shadow:none;-webkit-tap-highlight-color:transparent}
.site-header .icon-btn:hover,.menu-panel .icon-btn:hover{background:transparent}
.icon-btn:focus,.icon-btn:focus-visible{outline:none;box-shadow:none}
html.tb-keyboard .icon-btn:focus-visible,html.tb-keyboard .rail-controls button:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.news-rail-wrap .rail-controls{position:absolute;inset:0;display:block;pointer-events:none;margin:0}
.news-rail-wrap .rail-controls button{position:absolute;top:var(--rail-control-y,25%);transform:translateY(-50%);display:grid;place-items:center;width:28px;height:28px;padding:0;border:0;border-radius:3px;background:#fff;color:var(--red);box-shadow:0 1px 6px #0002;pointer-events:auto;-webkit-tap-highlight-color:transparent}
.news-rail-wrap .rail-controls .rail-prev{left:-12px}
.news-rail-wrap .rail-controls .rail-next{right:-12px}
.news-rail-wrap .rail-controls button:hover{background:#fff;color:var(--red);border:0}
.news-rail-wrap .rail-controls button .mdi-icon{width:20px;height:20px}
.news-rail-wrap .rail-controls button:focus,.news-rail-wrap .rail-controls button:focus-visible{outline:none}
html.tb-keyboard .news-rail-wrap .rail-controls button:focus-visible{outline:2px solid var(--ink);outline-offset:3px}


/* TBTimes v1.0.2: centered footer and mobile ad spacing. */
.footer{padding-top:44px}
.footer-top{display:flex;flex-direction:column;align-items:center;gap:0;text-align:center;max-width:760px}
.footer-logo{margin:0 0 16px;font-size:32px}
.footer #ttAbout{max-width:480px}
.footer p{max-width:480px;font-size:13px;line-height:1.85}
.footer-information{margin:26px 0 30px;width:100%}
.footer-pages{flex-direction:row;justify-content:center;gap:12px 0;font-size:13px;font-weight:600;line-height:1.5}
.footer-pages a{padding:0 14px}
.footer-pages a+a{border-left:1px solid #a9aaac}
.footer h2{margin:0 0 16px;font-size:13px;font-weight:400;color:#d0d0d2}
.social-links{justify-content:center;gap:14px}
.social-links a{width:42px;height:42px;border:1.2px solid #d0d0d2;color:#f5f5f5;-webkit-tap-highlight-color:transparent}
.social-links .mdi-icon{width:22px;height:22px}
.social-links [data-icon="mdi:alpha-x"]{transform:scale(1.6)}
.social-links a:focus-visible,.footer-pages a:focus-visible{outline:2px solid #fff;outline-offset:4px}
.footer-bottom{justify-content:center;position:relative;text-align:center;border-color:#ffffff65;margin-top:34px;padding:24px 44px 28px;font-size:12px;line-height:1.7;color:#c9c9cb}
.back-top{position:absolute;right:0;top:20px;border-radius:5px}
@media(max-width:768px){
 .footer{padding-top:40px}
 .footer-logo{font-size:30px;margin-bottom:16px}
 .footer #ttAbout{max-width:330px}
 .footer p{font-size:12px;line-height:1.85}
 .footer-information{margin:24px 0 30px}
 .footer-pages{font-size:12px}
 .footer-pages a{padding:0 10px}
 .social-links{display:grid;grid-template-columns:repeat(4,44px);gap:12px 14px}
 .social-links a{width:44px;height:44px}
 .social-links a:nth-child(5):nth-last-child(2){grid-column:2}
 .footer-bottom{font-size:11px;margin-top:30px;padding:22px 34px 25px}
 .back-top{top:19px;width:28px;height:28px}
 .ad-slot.tb-mobile-ad-duplicate,#ttAdBottom.tb-mobile-ad-suppressed{display:none!important}
 body.has-bottom-ad{padding-bottom:0}
}


/* TemaBlogger shared News Index v1.0.0. Theme color and font are inherited. */
.tbni{--tbni-accent:var(--red,#df1529);--tbni-ink:var(--ink,#25272a);--tbni-line:#e7e8eb;color:var(--tbni-ink);margin:26px 0 40px;font-family:inherit;min-width:0}
.tbni *{box-sizing:border-box}
.tbni[hidden],.tbni [hidden]{display:none!important}
.tbni a{color:inherit;text-decoration:none}
.tbni .tbni-breadcrumb{display:flex;gap:8px;align-items:center;color:#82858c;font-size:11px;margin-bottom:18px}
.tbni-breadcrumb a:hover{color:var(--tbni-accent)}
.tbni .tbni-heading{font-size:36px;font-weight:800;letter-spacing:-1.1px;line-height:1.2;margin:0 0 12px}
.tbni-intro{font-size:13px;line-height:1.8;color:#777b83;margin:0 0 26px;max-width:560px}
.tbni-intro:before{content:"";display:block;width:42px;height:4px;background:var(--tbni-accent);margin:18px 0;border-radius:2px}
.tbni .tbni-form{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 118px;gap:14px;align-items:end;padding:20px;background:#f7f8fa;border:1px solid #eceef1;border-radius:10px;margin:0 0 18px}
.tbni-field{display:block;min-width:0;font-size:11px;font-weight:600}
.tbni-field>span{display:block;margin-bottom:8px}
.tbni-control{position:relative;display:flex;align-items:center;min-width:0}
.tbni-control>.tbni-icon{position:absolute;left:12px;width:19px;height:19px;pointer-events:none;color:#858994}
.tbni input,.tbni select,.tbni button{font-family:inherit;font-size:12px}
.tbni input,.tbni select{width:100%;min-width:0;max-width:100%;height:44px;border:1px solid #dfe2e7;border-radius:6px;background:#fff;color:var(--tbni-ink);padding:0 10px 0 39px;line-height:normal}
.tbni select{padding-right:25px;text-overflow:ellipsis}
.tbni input[type=date]{color-scheme:light}
.tbni .tbni-submit{height:44px;border:1px solid var(--tbni-accent);border-radius:6px;background:var(--tbni-accent);color:#fff;font-weight:600;display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer}
.tbni-icon{display:inline-block;width:20px;height:20px;fill:currentColor;flex-shrink:0;vertical-align:middle}
.tbni-channels{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding:1px 1px 12px;margin-bottom:12px}
.tbni-channels::-webkit-scrollbar{display:none}
.tbni .tbni-chip{flex-shrink:0;white-space:nowrap;border:1px solid #e3e5e9;border-radius:20px;padding:8px 14px;color:#676b73;background:#fff;cursor:pointer;font-size:11px;line-height:1.4}
.tbni .tbni-chip[aria-pressed=true]{border-color:var(--tbni-accent);color:var(--tbni-accent);background:color-mix(in srgb,var(--tbni-accent) 6%,white);font-weight:600}
.tbni-summary{display:flex;justify-content:space-between;gap:14px;align-items:center;border-bottom:1px solid var(--tbni-line);padding-bottom:16px;margin-bottom:24px}
.tbni .tbni-count{font-weight:700;font-size:14px;margin:0 0 4px}
.tbni-context{font-size:11px;line-height:1.6;color:#8a8d94;margin:0}
.tbni .tbni-reset{background:none;border:0;color:var(--tbni-accent);padding:8px 0 8px 8px;min-height:40px;cursor:pointer;font-size:11px;white-space:nowrap}
.tbni .tbni-day{margin-bottom:26px}
.tbni .tbni-date{display:flex;align-items:center;gap:9px;font-size:14px;font-weight:700;line-height:1.5;margin:0;padding:12px 14px;background:#f5f6f8;border-left:3px solid var(--tbni-accent);border-radius:0 5px 5px 0}
.tbni-date .tbni-icon{width:18px;height:18px;color:var(--tbni-accent)}
.tbni .tbni-row{display:grid;grid-template-columns:58px minmax(0,1fr) 132px;gap:18px;align-items:center;padding:21px 0;border-bottom:1px solid var(--tbni-line)}
.tbni-time{align-self:start;padding-top:3px;font-size:12px;font-weight:600;color:#858994;line-height:1.6;font-variant-numeric:tabular-nums}
.tbni-time small{display:block;font-size:9px;font-weight:400;letter-spacing:.4px;color:#a1a4aa;margin-top:2px}
.tbni-copy{min-width:0}
.tbni .tbni-category{display:inline-block;color:var(--tbni-accent);font-size:10px;font-weight:600;margin:0 0 7px;line-height:1.4}
.tbni .tbni-title{font-size:16px;font-weight:700;line-height:1.55;letter-spacing:-.15px;margin:0;overflow-wrap:anywhere}
.tbni-title a:hover{color:var(--tbni-accent)}
.tbni .tbni-photo{display:grid;place-items:center;aspect-ratio:16/10;align-self:start;overflow:hidden;border-radius:6px;background:#f0f1f4;color:#b2b5bc}
.tbni-photo img{display:block;width:100%;height:100%;object-fit:cover}
.tbni-photo>.tbni-icon{width:30px;height:30px}
.tbni-more-area{text-align:center;padding:4px 0}
.tbni-progress{color:#8a8d94;font-size:11px;line-height:1.6;margin:0 0 14px}
.tbni .tbni-more,.tbni .tbni-retry{display:inline-flex;justify-content:center;align-items:center;gap:10px;border:1px solid var(--tbni-accent);border-radius:6px;min-height:44px;background:#fff;color:var(--tbni-accent);padding:10px 24px;font-size:12px;font-weight:600;cursor:pointer}
.tbni button:disabled{opacity:.55;cursor:wait}
.tbni button:focus-visible,.tbni input:focus-visible,.tbni select:focus-visible,.tbni a:focus-visible{outline:2px solid var(--tbni-accent);outline-offset:3px}
.tbni .tbni-notice{padding:32px 20px;border:1px solid var(--tbni-line);background:#fafbfc;border-radius:8px;text-align:center;margin-bottom:22px}
.tbni-notice>.tbni-icon{width:36px;height:36px;color:#afb3bd;margin-bottom:8px}
.tbni .tbni-notice h2{font-size:17px;line-height:1.5;margin:0 0 8px}
.tbni .tbni-notice p{font-size:12px;line-height:1.8;color:#80848d;margin:0 0 16px}
.tbni .tbni-native-link{display:block;font-size:11px;color:#80848d;margin-top:14px;text-decoration:underline}
.tbni-loading .tbni-ghost{height:120px;border-bottom:1px solid var(--tbni-line);background:linear-gradient(90deg,#f4f5f7 0 9%,transparent 9% 13%,#f4f5f7 13% 75%,transparent 75%);margin:0 0 12px;opacity:.7}
.has-tb-news-index .tb-index-native{display:none}
@media(max-width:600px){
 .tbni{margin-top:22px}
 .tbni .tbni-heading{font-size:30px;letter-spacing:-.8px}
 .tbni-intro{font-size:12px;margin-bottom:22px}
 .tbni .tbni-form{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px 10px;padding:16px}
 .tbni .tbni-submit{grid-column:1/-1}
 .tbni input,.tbni select{font-size:11px;padding-left:32px}
 .tbni-control>.tbni-icon{left:9px;width:17px;height:17px}
 .tbni input[type=date]{padding-right:4px}
 .tbni .tbni-row{grid-template-columns:39px minmax(0,1fr) 86px;gap:10px;padding:18px 0}
 .tbni .tbni-title{font-size:13px;line-height:1.6;letter-spacing:-.1px}
 .tbni-time{font-size:10px}
 .tbni-time small{font-size:8px}
 .tbni .tbni-category{font-size:9px;margin-bottom:5px}
 .tbni .tbni-date{font-size:12px;padding:11px 10px}
 .tbni .tbni-count{font-size:13px}
 .tbni-context{font-size:10px}
 .tbni .tbni-photo{border-radius:5px}
}
@media(max-width:360px){.tbni .tbni-row{grid-template-columns:35px minmax(0,1fr) 72px;gap:8px}.tbni .tbni-title{font-size:12px}.tbni .tbni-form{padding:12px;gap:12px 8px}.tbni input,.tbni select{padding-left:28px}.tbni-control>.tbni-icon{left:7px;width:16px;height:16px}}


/* TBTimes v1.2.0: product identity and standard TemaBlogger credit. */
.footer-logo{max-width:100%;overflow-wrap:anywhere;justify-content:center;text-align:center}
.tb-activation-help{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:5px;margin:0;padding:16px 20px;background:#fafbfe;border-top:1px solid #eaf0f7;color:#8893a6;font:10px/16px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;text-align:center}
.tb-activation-help svg{width:13px;height:13px;flex-shrink:0}.tb-activation-help a{color:#48618e;text-decoration:none}.tb-activation-help a:hover{text-decoration:underline}

.tbd-license-gate[hidden],.tbd-license-shield[hidden],.tbd-license-status[hidden],#tbd-license-context[hidden]{display:none!important}
.tbd-license-gate,.tbd-license-gate *,.tbd-license-status,.tbd-license-status *{box-sizing:border-box}
.tbd-license-gate{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;overflow:auto;padding:24px 16px;background:rgba(15,23,42,.55);font-family:Arial,system-ui,sans-serif;color:#172339;text-align:left;line-height:1.6}
.tbd-license-card{width:100%;max-width:460px;margin:auto;padding:30px;background:#fff;border:1px solid #e5eaf2;border-radius:22px;box-shadow:0 24px 80px #0f172a40}
.tbd-license-brand{display:inline-flex;align-items:center;gap:8px;color:#172339!important;text-decoration:none!important;font:bold 21px/1.3 Arial,sans-serif;letter-spacing:-.6px}
.tbd-license-brand b{color:#2456d9}.tbd-license-logo{position:relative;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;color:#fff;background:#2456d9;font:bold 24px/1 Arial,sans-serif;letter-spacing:0}.tbd-license-logo>span{position:absolute;right:5px;bottom:5px;width:6px;height:6px;border-radius:50%;background:#ffb300}
.tbd-license-symbol{display:grid;place-items:center;width:54px;height:54px;margin-top:28px;margin-bottom:16px;border-radius:15px;background:#edf2ff;color:#2456d9}
.tbd-license-eyebrow{margin:0 0 8px!important;color:#526178;font:bold 11px/1.5 Arial,sans-serif;letter-spacing:1.3px}
.tbd-license-card h2{margin:0 0 14px!important;padding:0;color:#172339;font:bold 26px/1.25 Arial,sans-serif;letter-spacing:-.7px;overflow-wrap:anywhere}
.tbd-license-card #tbd-license-description{margin:0 0 24px!important;color:#526178;font:15px/1.7 Arial,sans-serif;overflow-wrap:anywhere}
.tbd-license-card strong{color:#172339;font-weight:700}
.tbd-license-actions{display:grid;gap:10px}
.tbd-license-actions a{display:flex;justify-content:center;align-items:center;min-height:48px;padding:12px 16px;border:1px solid #2456d9;border-radius:11px;background:#2456d9;color:#fff!important;text-decoration:none!important;font:bold 15px/1.45 Arial,sans-serif;text-align:center;overflow-wrap:anywhere}
.tbd-license-actions a:hover{background:#173fa9;border-color:#173fa9}.tbd-license-actions .tbd-license-secondary{background:#fff;color:#2456d9!important;border-color:#d3ddef}.tbd-license-actions .tbd-license-secondary:hover{background:#f5f7fb}
#tbd-license-check{display:block;margin:18px auto 0;padding:6px 3px;border:0;background:transparent;color:#526178;font:14px/1.5 Arial,sans-serif;text-align:center;text-decoration:underline;text-underline-offset:4px;cursor:pointer}
.tbd-license-gate :focus-visible,.tbd-license-status button:focus-visible{outline:3px solid #9db5ff;outline-offset:3px}
.tbd-license-modal{overflow:hidden}.tbd-license-shield{position:fixed;inset:0;z-index:2147482000;background:transparent}
.tbd-license-status{position:fixed;z-index:2147483001;left:50%;bottom:18px;transform:translateX(-50%);width:calc(100% - 32px);max-width:440px;padding:16px 18px;border:1px solid #e5eaf2;border-radius:12px;background:#fff;color:#526178;box-shadow:0 6px 30px #0f172a20;font:14px/1.6 Arial,sans-serif}
.tbd-license-status button{display:block;margin-top:8px;padding:7px 12px;border:0;border-radius:8px;background:#2456d9;color:#fff;font:bold 13px/1.5 Arial,sans-serif;cursor:pointer}
@media(max-width:380px){.tbd-license-card{padding:24px 20px}.tbd-license-card h2{font-size:23px}}


